// Replaces o.R.AppWorkspaceSCMConnections with related.
// Sets related.R.App's AppWorkspaceSCMConnections accordingly.
func (o *SCMApp) SetAppWorkspaceSCMConnections(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*WorkspaceSCMConnection) error {
	query := "update \"workspace_scm_connections\" set \"app_id\" = null where \"app_id\" = $1"
	values := []any{o.ID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.AppWorkspaceSCMConnections {
			queries.SetScanner(&rel.AppID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.App = nil
		}
		o.R.AppWorkspaceSCMConnections = nil
	}

	return o.AddAppWorkspaceSCMConnections(ctx, exec, insert, related...)
}

// RemoveAppWorkspaceSCMConnections relationships from objects passed in.
// Removes related items from R.AppWorkspaceSCMConnections (uses pointer comparison, removal does not keep order)
// Sets related.R.App.
func (o *SCMApp) RemoveAppWorkspaceSCMConnections(ctx context.Context, exec boil.ContextExecutor, related ...*WorkspaceSCMConnection) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.AppID, nil)
		if rel.R != nil {
			rel.R.App = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("app_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.AppWorkspaceSCMConnections {
			if rel != ri {
				continue
			}

			ln := len(o.R.AppWorkspaceSCMConnections)
			if ln > 1 && i < ln-1 {
				o.R.AppWorkspaceSCMConnections[i] = o.R.AppWorkspaceSCMConnections[ln-1]
			}
			o.R.AppWorkspaceSCMConnections = o.R.AppWorkspaceSCMConnections[:ln-1]
			break
		}
	}

	return nil
}

// SCMApps retrieves all the records using an executor.
func SCMApps(mods ...qm.QueryMod) scmAppQuery {
	mods = append(mods, qm.From("\"scm_apps\""))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"\"scm_apps\".*"})
	}

	return scmAppQuery{q}
}

// FindSCMApp retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindSCMApp(ctx context.Context, exec boil.ContextExecutor, iD string, selectCols ...string) (*SCMApp, error) {
	scmAppObj := &SCMApp{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"scm_apps\" where \"id\"=$1", sel,
	)

	q := queries.Raw(query, iD)

	err := q.Bind(ctx, exec, scmAppObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "dbpostgres: unable to select from scm_apps")
	}

	if err = scmAppObj.doAfterSelectHooks(ctx, exec); err != nil {
		return scmAppObj, err
	}

	return scmAppObj, nil
}

// Insert a single record using an executor.
// See boil.Columns.InsertColumnSet documentation to understand column list inference for inserts.
func (o *SCMApp) Insert(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) error {
	if o == nil {
		return errors.New("dbpostgres: no scm_apps provided for insertion")
	}

	var err error
	if !boil.TimestampsAreSkipped(ctx) {
		currTime := time.Now().In(boil.GetLocation())

		if o.CreatedAt.IsZero() {
			o.CreatedAt = currTime
		}
		if o.UpdatedAt.IsZero() {
			o.UpdatedAt = currTime
		}
	}

	if err := o.doBeforeInsertHooks(ctx, exec); err != nil {
		return err
	}

	nzDefaults := queries.NonZeroDefaultSet(scmAppColumnsWithDefault, o)

	key := makeCacheKey(columns, nzDefaults)
	scmAppInsertCacheMut.RLock()
	cache, cached := scmAppInsertCache[key]
	scmAppInsertCacheMut.RUnlock()

	if !cached {
		wl, returnColumns := columns.InsertColumnSet(
			scmAppAllColumns,
			scmAppColumnsWithDefault,
			scmAppColumnsWithoutDefault,
			nzDefaults,
		)

		cache.valueMapping, err = queries.BindMapping(scmAppType, scmAppMapping, wl)
		if err != nil {
			return err
		}
		cache.retMapping, err = queries.BindMapping(scmAppType, scmAppMapping, returnColumns)
		if err != nil {
			return err
		}
		if len(wl) != 0 {
			cache.query = fmt.Sprintf("INSERT INTO \"scm_apps\" (\"%s\") %%sVALUES (%s)%%s", strings.Join(wl, "\",\""), strmangle.Placeholders(dialect.UseIndexPlaceholders, len(wl), 1, 1))
		} else {
			cache.query = "INSERT INTO \"scm_apps\" %sDEFAULT VALUES%s"
		}

		var queryOutput, queryReturning string

		if len(cache.retMapping) != 0 {
			queryReturning = fmt.Sprintf(" RETURNING \"%s\"", strings.Join(returnColumns, "\",\""))
		}

		cache.query = fmt.Sprintf(cache.query, queryOutput, queryReturning)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	vals := queries.ValuesFromMapping(value, cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, vals)
	}

	if len(cache.retMapping) != 0 {
		err = exec.QueryRowContext(ctx, cache.query, vals...).Scan(queries.PtrsFromMapping(value, cache.retMapping)...)
	} else {
		_, err = exec.ExecContext(ctx, cache.query, vals...)
	}

	if err != nil {
		return errors.Wrap(err, "dbpostgres: unable to insert into scm_apps")
	}

	if !cached {
		scmAppInsertCacheMut.Lock()
		scmAppInsertCache[key] = cache
		scmAppInsertCacheMut.Unlock()
	}

	return o.doAfterInsertHooks(ctx, exec)
}

// Update uses an executor to update the SCMApp.
// See boil.Columns.UpdateColumnSet documentation to understand column list inference for updates.
// Update does not automatically update the record in case of default values. Use .Reload() to refresh the records.
func (o *SCMApp) Update(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) (int64, error) {
	if !boil.TimestampsAreSkipped(ctx) {
		currTime := time.Now().In(boil.GetLocation())

		o.UpdatedAt = currTime
	}

	var err error
	if err = o.doBeforeUpdateHooks(ctx, exec); err != nil {
		return 0, err
	}
	key := makeCacheKey(columns, nil)
	scmAppUpdateCacheMut.RLock()
	cache, cached := scmAppUpdateCache[key]
	scmAppUpdateCacheMut.RUnlock()

	if !cached {
		wl := columns.UpdateColumnSet(
			scmAppAllColumns,
			scmAppPrimaryKeyColumns,
		)

		if !columns.IsWhitelist() {
			wl = strmangle.SetComplement(wl, []string{"created_at"})
		}
		if len(wl) == 0 {
			return 0, errors.New("dbpostgres: unable to update scm_apps, could not build whitelist")
		}

		cache.query = fmt.Sprintf("UPDATE \"scm_apps\" SET %s WHERE %s",
			strmangle.SetParamNames("\"", "\"", 1, wl),
			strmangle.WhereClause("\"", "\"", len(wl)+1, scmAppPrimaryKeyColumns),
		)
		cache.valueMapping, err = queries.BindMapping(scmAppType, scmAppMapping, append(wl, scmAppPrimaryKeyColumns...))
		if err != nil {
			return 0, err
		}
	}

	values := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(o)), cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, values)
	}
	var result sql.Result
	result, err = exec.ExecContext(ctx, cache.query, values...)
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: unable to update scm_apps row")
	}

	rowsAff, err := result.RowsAffected()
	if err != nil {
		return 0, errors.Wrap(err, "dbpostgres: failed to get rows affected by update for scm_apps")
	}

	if !cached {
		scmAppUpdateCacheMut.Lock()
		scmAppUpdateCache[key] = cache
		scmAppUpdateCacheMut.Unlock()
	}

	return rowsAff, o.doAfterUpdateHooks(ctx, exec)
}

